create extension if not exists "pgjwt" with schema "extensions";


create extension if not exists "vector" with schema "public" version '0.8.0';

create table "public"."Ad per Ad Account" (
    "id" bigint generated by default as identity not null,
    "created_at" timestamp with time zone not null default now(),
    "ad_name" text,
    "account_id" text,
    "creative_id" text,
    "ad_text" text,
    "ad_title" text,
    "image" text,
    "video" text,
    "brand" text,
    "post_link" text,
    "Created At" timestamp with time zone,
    "Image_url" text,
    "video_url" text,
    "ad_id" text not null,
    "ad per account" text,
    "Angel" text,
    "Angel Type" text,
    "Explanation" text
);


create table "public"."Cluster Comments" (
    "id" bigint generated by default as identity not null,
    "created_at" timestamp with time zone not null default now(),
    "comment_id" text not null
);


create table "public"."Comment Claster" (
    "id" bigint generated by default as identity not null,
    "Cluster name" text,
    "Cluster Description" text,
    "Comment" text,
    "Ad" text,
    "meta_cluster" text,
    "created_at" timestamp with time zone not null default now(),
    "ad_id" text,
    "comment_id" text,
    "brand" text
);


create table "public"."Comments" (
    "id" bigint generated by default as identity not null,
    "comment_id" text,
    "message" text,
    "created_time" timestamp without time zone,
    "ad_id" text,
    "created_at" timestamp with time zone not null default now(),
    "theme" text,
    "sentiment" text,
    "brand" text
);


create table "public"."Prompt" (
    "id" bigint generated by default as identity not null,
    "Prompts" text,
    "Name" text,
    "Examples" text,
    "created_at" timestamp with time zone not null default now()
);


create table "public"."comment_assignments" (
    "assignment_id" uuid not null default gen_random_uuid(),
    "comment_id" character varying(255) not null,
    "cluster_id" uuid not null,
    "similarity_score" double precision,
    "assignment_method" character varying(50),
    "confidence_score" double precision,
    "llm_reasoning" text,
    "assigned_at" timestamp with time zone default now()
);


create table "public"."comment_clusters" (
    "cluster_id" uuid not null default gen_random_uuid(),
    "cluster_name" character varying(255),
    "cluster_description" text,
    "meta_cluster" character varying(100),
    "ad_id" character varying(100),
    "centroid_embedding" vector(1536) not null,
    "comment_count" integer default 1,
    "sample_comments" text[] default '{}'::text[],
    "avg_similarity_score" double precision default 0.0,
    "cluster_cohesion" double precision default 0.0,
    "created_at" timestamp with time zone default now(),
    "updated_at" timestamp with time zone default now(),
    "content" text,
    "metadata" jsonb,
    "embedding" vector(1536)
);


create table "public"."comments" (
    "comment_id" character varying(255) not null,
    "ad_id" character varying(100) not null,
    "comment_text" text not null,
    "author_name" character varying(255),
    "likes_count" integer default 0,
    "replies_count" integer default 0,
    "sentiment_score" double precision,
    "theme" character varying(500),
    "sentiment" character varying(50),
    "embedding" vector(1536),
    "embedding_model" character varying(50) default 'text-embedding-3-small'::character varying,
    "comment_created_at" timestamp with time zone,
    "processed_at" timestamp with time zone default now()
);


create table "public"."report_metadata" (
    "id" uuid not null,
    "title" text not null,
    "brand" text not null,
    "created" timestamp with time zone not null,
    "adcount" integer not null
);


create table "public"."reports" (
    "id" uuid not null,
    "data" jsonb not null,
    "created_at" timestamp with time zone default now()
);


