CREATE TRIGGER set_brand_on_comment_cluster BEFORE INSERT OR UPDATE ON public."Comment Claster" FOR EACH ROW EXECUTE FUNCTION update_comment_cluster_brand_from_ad_account();

CREATE TRIGGER set_brand_on_comment BEFORE INSERT OR UPDATE ON public."Comments" FOR EACH ROW EXECUTE FUNCTION set_comment_brand();

CREATE TRIGGER populate_cluster_trigger BEFORE INSERT ON public.comment_clusters FOR EACH ROW EXECUTE FUNCTION populate_cluster_from_metadata();


